:root {
  /* Polar Night */
  --nord0: #2e3440;
  --nord1: #3b4252;
  --nord2: #434c5e;
  --nord3: #4c566a; /*220 16% 36%*/

  /* Snow Storm */
  --nord4: #d8dee9; /*219 28% 88%*/
  --nord5: #e5e9f0;
  --nord6: #eceff4;

  /* Frost */
  --nord7: #8fbcbb; /*179 25% 65%*/
  --nord8: #88c0d0; /*193 43% 67%*/
  --nord9: #81a1c1; /*210 34% 63%*/
  --nord10: #5e81ac; /*213 32% 52%*/

  /* Aurora */
  --nord11: #bf616a;
  --nord12: #d08770;
  --nord13: #ebcb8b;
  --nord14: #a3be8c;
  --nord15: #b48ead;
}

body
{
  /* Editor */
    /* Headings */
    --h1-color: var(--nord8);
    --h2-color: var(--nord7);
    --h3-color: var(--nord9);
    --h4-color: var(--nord10);
    /* Link */
    --link-color: #0b62e5;
    --link-external-color: #0b62e5;
  /* Foundations */
    /* Typography */
      /* Fonts */
      --font-interface-theme: Pending Mono HWNF;
      --font-text-theme: Pending Mono HWNF;
      --font-monospace-theme: Pending Mono HWNF;
}
 
.theme-dark
{
  /* Editor */
    /* Headings */
    --h5-color: var(--nord6);
    --h6-color: var(--nord5);
    /* Inline title */
    --inline-title-color: var(--nord4);
    /* Table */
    --table-border-color: var(--nord3);

  /* Foundation */
    /* Colors */
      /* Accent color */
      /* nord4 */
      --accent-h: 219;
      --accent-s: 28%;
      --accent-l: 88%;
      /* Semantic colors */
      --background-primary: var(--nord0);
      --background-secondary: var(--nord1);
}

.theme-light
{
  /* Editor */
    /* Headings */
    --h5-color: var(--nord1);
    --h6-color: var(--nord0);
    /* Inline title */
    --inline-title-color: var(--nord3);
    /* Table */
    --table-border-color: var(--nord4);

  /* Foundation */
    /* Colors */
      /* Accent color */
      /* nord4 */
      --accent-h: 220;
      --accent-s: 16%;
      --accent-l: 36%;
      /* Semantic colors */
      --background-primary: #FFFFFF;
      --background-secondary: #f2f4f8;
}

@font-face { 
  font-family: "Pending Mono HWNF";
  font-weight: normal;
  font-style: normal;
  src: url(data:application/font-woff;base64,);
}

@font-face { 
  font-family: "Pending Mono HWNF";
  font-weight: bold;
  font-style: normal;
  src: url(data:application/font-woff;base64,);
}

@font-face { 
  font-family: "Pending Mono HWNF";
  font-weight: normal;
  font-style: italic;
  src: url(data:application/font-woff;base64,);
}

@font-face { 
  font-family: "Pending Mono HWNF";
  font-weight: bold;
  font-style: italic;
  src: url(data:application/font-woff;base64,);
}
